import FoundationModels

@Generable
struct TripPlan {
    @Guide(description: "Short title") var title: String
    @Guide(description: "Three activities", .count(3)) var activities: [String]
}

func plan(for city: String) async throws -> TripPlan? {
    guard case .available = SystemLanguageModel.default.availability else { return nil }
    let session = LanguageModelSession(instructions: "You plan short city trips.")
    return try await session.respond(to: "Plan a day in \(city)", generating: TripPlan.self).content
}
